function markerDistances(s: string, c: string): number[] {
  const marks: number[] = [];
  for (let i = 0; i < s.length; i++) if (s[i] === c) marks.push(i);
  const out: number[] = [];
  for (let i = 0; i < s.length; i++) {
    let best = Infinity;
    for (const m of marks) best = Math.min(best, Math.abs(i - m));
    out.push(best);
  }
  return out;
}

