function markerDistances(s: string, c: string): number[] {
  const n = s.length;
  const out = new Array<number>(n);
  let last = -Infinity;
  for (let i = 0; i < n; i++) {
    if (s[i] === c) last = i;
    out[i] = i - last;
  }
  last = Infinity;
  for (let i = n - 1; i >= 0; i--) {
    if (s[i] === c) last = i;
    out[i] = Math.min(out[i], last - i);
  }
  return out;
}

